tools.descriptions.el:
[
  {
    "type": "function",
    "function": {
      "name": "search_knowledge",
      "description": "Search the guitar-teaching knowledge base for raw excerpts relevant to a query (technique, theory, gear, tone). Returns a ranked list of short excerpts with their source title and similarity score. Use explain_concept instead when you want a ready-written, cited answer rather than raw excerpts.",
      "parameters": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "what to search for"
          },
          "k": {
            "type": "integer",
            "description": "how many results to return (default 8)"
          }
        },
        "required": [
          "query"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "explain_concept",
      "description": "Get a grounded, cited explanation of a guitar concept from the knowledge base. Use this for 'what is X' / 'explain X' questions — it returns a ready-to-use written answer plus its citations, strictly grounded in retrieved material (never invented).",
      "parameters": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "the concept or question to explain"
          },
          "k": {
            "type": "integer",
            "description": "how many source chunks to ground the answer in (default 8)"
          }
        },
        "required": [
          "query"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "search_concepts",
      "description": "Search the CONCEPT CANON — the tutor's ENTIRE library distilled into concepts, each carrying what EVERY book says about it. Use this for 'what do my books say about X?' / 'do my books agree on X?' questions (pickup height, tone, bias, string gauge, technique). Unlike search_knowledge, which returns raw excerpts from a SINGLE book, this returns the CROSS-BOOK picture: where the books agree, and — most valuable — where they DISAGREE, with each author's own position and its real page citations. When a result reports divergence:true, TEACH THE DISAGREEMENT: present BOTH positions with their citations and let the tutor choose — never average two disagreeing authors into one bland claim. A citation with grounding:'figure' is our description of a picture/diagram — cite it, never quote it as the author's words.",
      "parameters": {
        "type": "object",
        "properties": {
          "query": {
            "type": "string",
            "description": "the concept or topic to look up across all the books"
          },
          "k": {
            "type": "integer",
            "description": "how many concepts to return (default 6)"
          }
        },
        "required": [
          "query"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "list_students",
      "description": "List every student on the roster (id, name, level, instrument, status). Use this to look up a student's id before calling a tool that needs one, or to answer 'who are my students' type questions.",
      "parameters": {
        "type": "object",
        "properties": {},
        "required": []
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "list_curricula",
      "description": "List every curriculum template (id, title, language, created_at). Use this to find a curriculum's root id before calling get_curriculum.",
      "parameters": {
        "type": "object",
        "properties": {},
        "required": []
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "list_artifacts",
      "description": "List generated/uploaded teaching artifacts (id, kind, title, tags, block_id), optionally filtered by the block/lesson they're attached to or by kind (e.g. 'chord_diagram', 'tab', 'tone_recipe').",
      "parameters": {
        "type": "object",
        "properties": {
          "block_id": {
            "type": "string",
            "description": "optional: only artifacts attached to this block id (UUID)"
          },
          "kind": {
            "type": "string",
            "description": "optional: only this artifact kind"
          }
        },
        "required": []
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "get_curriculum",
      "description": "Get the full content tree (course -> modules -> lessons -> segments, with titles/objectives/bodies) for one curriculum by its root id. Call list_curricula first if you don't already have the id.",
      "parameters": {
        "type": "object",
        "properties": {
          "root_id": {
            "type": "string",
            "description": "the curriculum's root block id (UUID), from list_curricula"
          }
        },
        "required": [
          "root_id"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "propose_curriculum_revision",
      "description": "Draft STRUCTURAL changes to an EXISTING curriculum (add/move/modify/remove lessons and modules) — call this ONLY when the tutor EXPLICITLY asks to ADD, CHANGE, REMOVE, or RESTRUCTURE the course (e.g. 'add a lesson on the DS-1', 'split module 2', 'drop the theory lesson', 'reorder these'). It runs a slow retrieval-grounded planner, so do NOT call it to ANSWER a question ABOUT the course ('what is this lesson about?', 'how many modules are there?', 'is distortion covered?'): answer those DIRECTLY from the curriculum tree already in your context, reaching for find_lesson or search_knowledge only if you need more detail. Returns a PLAN of operations, each with a reason — it CHANGES NOTHING; apply_curriculum_revision is the gated step that applies an approved plan.",
      "parameters": {
        "type": "object",
        "properties": {
          "root_id": {
            "type": "string",
            "description": "the curriculum root id (from the conversation context)"
          },
          "instruction": {
            "type": "string",
            "description": "what the tutor wants changed, in his own words"
          }
        },
        "required": [
          "root_id",
          "instruction"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "find_lesson",
      "description": "Find a lesson by a partial, case-insensitive title match (e.g. \"pick gauge\" matches \"Pick Gauge and Tone\"). Use this BEFORE split_session/merge_sessions/add_session whenever you don't already have a real lesson/session id — never guess one. Returns each match's id, title, provenance (if drafted from a Library selection), and its sessions (id, title, order) so one call is usually enough.",
      "parameters": {
        "type": "object",
        "properties": {
          "title_query": {
            "type": "string",
            "description": "text to match against lesson titles"
          }
        },
        "required": [
          "title_query"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "create_student",
      "description": "Add a new student to the roster. This is a MUTATION — it requires the tutor's explicit approval before the student is actually created.",
      "parameters": {
        "type": "object",
        "properties": {
          "name": {
            "type": "string",
            "description": "the student's full name"
          },
          "birthdate": {
            "type": "string",
            "description": "optional: birthdate as YYYY-MM-DD"
          },
          "level": {
            "type": "string",
            "description": "optional: skill level, e.g. 'beginner', 'intermediate', 'advanced'"
          },
          "instrument": {
            "type": "string",
            "description": "optional: main instrument, e.g. 'guitar', 'bass'"
          },
          "preferred_language": {
            "type": "string",
            "description": "optional: 2-letter preferred language, e.g. 'en'/'el' (default 'el')"
          }
        },
        "required": [
          "name"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "update_student",
      "description": "Update fields on an existing student — a partial update, only the fields you provide are changed. This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "student_id": {
            "type": "string",
            "description": "the student's id (UUID), from list_students"
          },
          "name": {
            "type": "string",
            "description": "optional: new name"
          },
          "birthdate": {
            "type": "string",
            "description": "optional: new birthdate, YYYY-MM-DD"
          },
          "level": {
            "type": "string",
            "description": "optional: new skill level"
          },
          "instrument": {
            "type": "string",
            "description": "optional: new main instrument"
          },
          "preferred_language": {
            "type": "string",
            "description": "optional: new preferred language, e.g. 'en'/'el'"
          }
        },
        "required": [
          "student_id"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "segment_block",
      "description": "Partition a curriculum block's content into ~session_minutes teaching sessions on the delivery plane. Replaces any existing session plan for the same block/student. This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "block_id": {
            "type": "string",
            "description": "the curriculum block id (UUID) to segment, from list_curricula/get_curriculum"
          },
          "session_minutes": {
            "type": "integer",
            "description": "target minutes per teaching session"
          },
          "cadence_per_week": {
            "type": "integer",
            "description": "optional: sessions per week (default 1)"
          },
          "student_id": {
            "type": "string",
            "description": "optional: scope the delivery plan to this student id (UUID); omit for the template's unscoped plan"
          }
        },
        "required": [
          "block_id",
          "session_minutes"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "update_block",
      "description": "Update fields on a curriculum block (course/module/lesson/segment/session) — a partial update, only the fields you provide are changed. This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "block_id": {
            "type": "string",
            "description": "the block id (UUID) to update"
          },
          "title": {
            "type": "string",
            "description": "optional: new title (cannot be empty)"
          },
          "body": {
            "type": "string",
            "description": "optional: new body/description text"
          },
          "est_minutes": {
            "type": "integer",
            "description": "optional: new estimated minutes"
          },
          "order": {
            "type": "integer",
            "description": "optional: new sibling order"
          },
          "kind": {
            "type": "string",
            "description": "optional: new kind label"
          }
        },
        "required": [
          "block_id"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "assign_curriculum",
      "description": "Assign a curriculum template to a student: deep-clones the template's content tree for that student and records the assignment. This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "root_id": {
            "type": "string",
            "description": "the curriculum template's root block id (UUID), from list_curricula"
          },
          "student_id": {
            "type": "string",
            "description": "the student id (UUID) to assign it to, from list_students"
          }
        },
        "required": [
          "root_id",
          "student_id"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "generate_artifact",
      "description": "Generate a new teaching artifact (chord diagram, scale, tab, tone recipe, signal chain, amp dial settings, gear card) from a free-text prompt using the LLM, and persist it. This is a MUTATION — it requires the tutor's explicit approval before it's actually generated and saved.",
      "parameters": {
        "type": "object",
        "properties": {
          "kind": {
            "type": "string",
            "description": "artifact kind, e.g. 'chord_diagram', 'scale', 'tab', 'tone_recipe', 'signal_chain', 'amp_settings', 'gear_card'"
          },
          "prompt": {
            "type": "string",
            "description": "free-text description of what to generate"
          },
          "block_id": {
            "type": "string",
            "description": "optional: attach the artifact to this curriculum block id (UUID)"
          },
          "ground": {
            "type": "boolean",
            "description": "optional: ground the generation in the knowledge base (default false)"
          }
        },
        "required": [
          "kind",
          "prompt"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "generate_curriculum",
      "description": "Author a brand-new curriculum (course -> modules -> lessons) by reading the tutor's ENTIRE library and outlining from it, then drafting every lesson in the background. Slow — runs as a background job once approved, and the tutor watches the lessons arrive. This is a MUTATION — it requires his explicit approval before it starts.",
      "parameters": {
        "type": "object",
        "properties": {
          "title": {
            "type": "string",
            "description": "the course title"
          },
          "brief": {
            "type": "string",
            "description": "what this course is FOR, in the tutor's own words — what the student should be able to do at the end"
          },
          "weeks": {
            "type": "integer",
            "description": "how many weeks the course runs (one session a week)"
          },
          "minutes_per_session": {
            "type": "integer",
            "description": "minutes per session, e.g. 50"
          },
          "student_id": {
            "type": "string",
            "description": "optional: the student this is for. Omit it for a course aimed at no one in particular — that is a normal, expected answer, not a missing field."
          },
          "profile": {
            "type": "object",
            "description": "optional: target profile, e.g. {\"level\": \"beginner\"}"
          }
        },
        "required": [
          "title"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "apply_curriculum_revision",
      "description": "Apply a revision plan produced by propose_curriculum_revision to the curriculum. This is a MUTATION — it requires the tutor's explicit approval before anything changes. Pass the EXACT plan object propose returned; on approval the new/changed lessons are drafted in the background and the tutor watches them arrive.",
      "parameters": {
        "type": "object",
        "properties": {
          "root_id": {
            "type": "string",
            "description": "the curriculum root id (from the conversation context)"
          },
          "plan": {
            "type": "object",
            "description": "the plan object from propose_curriculum_revision"
          }
        },
        "required": [
          "root_id",
          "plan"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "add_note",
      "description": "Add a free-form teaching note — e.g. an observation about a student's progress, a technique they struggled with, or a reminder for next lesson. This is a MUTATION — it requires the tutor's explicit approval before it's actually saved.",
      "parameters": {
        "type": "object",
        "properties": {
          "title": {
            "type": "string",
            "description": "a short title for the note"
          },
          "body": {
            "type": "string",
            "description": "the note's content"
          },
          "tags": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "optional: free-form tags, e.g. ['technique', 'chords']"
          },
          "student_id": {
            "type": "string",
            "description": "optional: the student id (UUID) this note is about, from list_students"
          }
        },
        "required": [
          "title",
          "body"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "promote_note_to_knowledge",
      "description": "Promote an existing note into the knowledge base, so its content can ground future search/curriculum/artifact generation. This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "note_id": {
            "type": "string",
            "description": "the note id (UUID) to promote, from list_students/context"
          }
        },
        "required": [
          "note_id"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "log_progress",
      "description": "Record or update a student's mastery status against a curriculum block — upserts, so calling this again for the same student+block replaces the prior status. This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "student_id": {
            "type": "string",
            "description": "the student id (UUID), from list_students"
          },
          "block_id": {
            "type": "string",
            "description": "the curriculum block id (UUID), from list_curricula/get_curriculum"
          },
          "status": {
            "type": "string",
            "description": "one of: not_started, introduced, practicing, mastered"
          },
          "notes": {
            "type": "string",
            "description": "optional: free-text notes about this progress update"
          }
        },
        "required": [
          "student_id",
          "block_id",
          "status"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "draft_lesson_from_selection",
      "description": "Draft a brand-new lesson (title, teaching sessions, items) grounded in a passage of text the tutor selected from a source in the Library — every session and item is generated FROM that exact passage, nothing invented. Slow (roughly 1-3 minutes) — runs as a background job once approved. This is a MUTATION — it requires the tutor's explicit approval before it starts.",
      "parameters": {
        "type": "object",
        "properties": {
          "source_id": {
            "type": "string",
            "description": "the knowledge source id (UUID) the passage was selected from"
          },
          "page_no": {
            "type": "integer",
            "description": "the page number the passage was selected from"
          },
          "text": {
            "type": "string",
            "description": "the exact passage text to ground the lesson in"
          }
        },
        "required": [
          "source_id",
          "page_no",
          "text"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "split_session",
      "description": "Split one over-long teaching session into several shorter ones, packed to ~session_minutes each — every item the session had is preserved, just re-grouped, in order. This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "session_id": {
            "type": "string",
            "description": "the session block id (UUID) to split (see get_curriculum for a lesson's session ids)"
          },
          "session_minutes": {
            "type": "integer",
            "description": "target minutes per resulting session"
          }
        },
        "required": [
          "session_id",
          "session_minutes"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "merge_sessions",
      "description": "Merge two or more ADJACENT teaching sessions of the same lesson into one, concatenating their items in order. Non-adjacent sessions are rejected (merging them would silently reorder whatever sits between them). This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "session_ids": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "at least 2 session block ids (UUID), in the order to concatenate them; must be adjacent sessions of the same lesson (see get_curriculum for a lesson's session ids)"
          }
        },
        "required": [
          "session_ids"
        ]
      }
    }
  },
  {
    "type": "function",
    "function": {
      "name": "add_session",
      "description": "Add a new, empty teaching session to a lesson — appended at the end by default, or inserted right after another session. This is a MUTATION — it requires the tutor's explicit approval before it's actually applied.",
      "parameters": {
        "type": "object",
        "properties": {
          "lesson_id": {
            "type": "string",
            "description": "the lesson block id (UUID) to add a session to"
          },
          "title": {
            "type": "string",
            "description": "the new session's title"
          },
          "est_minutes": {
            "type": "integer",
            "description": "optional: estimated minutes for the new session"
          },
          "after": {
            "type": "string",
            "description": "optional: insert immediately after this existing session id (UUID); omit to append at the end"
          }
        },
        "required": [
          "lesson_id",
          "title"
        ]
      }
    }
  }
]

